100	  /**
101	   * Zera o estoque de um produto individual na loja informada.
102	   *
103	   * Guard: lojaId ou produtoMasterId inválidos (null/undefined/0/NaN) retorna
104	   * ok:false sem chamar a RPC.
105	   */
106	  async function zerarProduto(
107	    produtoMasterId: number,
108	    lojaId: number,
109	  ): Promise<ZerarProdutoResult> {
110	    // Guard: entradas inválidas
111	    if (
112	      produtoMasterId == null ||
113	      !Number.isFinite(produtoMasterId) ||
114	      produtoMasterId <= 0
115	    ) {
116	      return { ok: false, erro: 'produtoMasterId inválido.' };
117	    }
118	    if (lojaId == null || !Number.isFinite(lojaId) || lojaId <= 0) {
119	      return { ok: false, erro: 'lojaId inválido.' };
120	    }
121	
122	    setIsZerando(true);
123	    try {
124	      const { data, error } = await supabase.rpc('zerar_estoque_produto', {
125	        p_produto_master_id: produtoMasterId,
126	        p_loja_id: lojaId,
127	      });
128	
129	      if (error) {
130	        return { ok: false, erro: error.message };
131	      }
132	
133	      await invalidarQueries();
134	      return data as ZerarProdutoResult;
135	    } finally {
136	      setIsZerando(false);
137	    }
138	  }
